function validate([nums, k, multiplier]) {
  if (nums.length < 1 || nums.length > 10000) return 'nums needs 1 to 10^4 values.';
  if (nums.some(v => v < 1 || v > 1000000000)) return 'Each value of nums is between 1 and 10^9.';
  if (k < 1 || k > 1000000000) return 'k is between 1 and 10^9.';
  if (multiplier < 1 || multiplier > 1000000) return 'multiplier is between 1 and 10^6.';
  return null;
}

