function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = pick(1900, 2000);
    // Mixing tiny and huge values makes the simulated phase long; small multipliers make it longer still.
    const nums = Array.from({ length: n }, () => rand() < 0.5 ? pick(1, 1000) : pick(1, 1000000000));
    const multiplier = [2, 3, pick(2, 1000000)][pick(0, 2)];
    return [nums, pick(1, 1000000000), multiplier];
  }
  const n = pick(1, 5);
  const top = [3, 30, 1000000000][pick(0, 2)];
  const nums = Array.from({ length: n }, () => pick(1, top));
  return [nums, pick(1, 60), [1, 2, 2, 3, 5, 1000000][pick(0, 5)]];
}
